const $=s=>document.querySelector(s);
export function initAuth(){
 const panel=document.createElement('div');panel.className='account-controls';panel.innerHTML='<span id="account-email"></span><button id="open-login">登入</button><button id="logout" hidden>登出</button>';document.querySelector('main>header').append(panel);
 const dialog=document.createElement('dialog');dialog.id='login-dialog';dialog.innerHTML='<button type="button" class="close" aria-label="關閉登入視窗">×</button><p class="eyebrow">ENCORE ACCOUNT</p><h2>登入你的帳號</h2><form id="login-form"><label for="login-email">Email</label><input id="login-email" type="email" name="email" autocomplete="username" maxlength="254" required><label for="login-password">Password</label><div class="password-field"><input id="login-password" type="password" name="password" autocomplete="current-password" maxlength="1024" required><button id="show-password" type="button" aria-pressed="false">顯示</button></div><p id="login-message" role="status" aria-live="polite"></p><button id="login-submit" class="primary" type="submit">登入</button></form>';document.body.append(dialog);
 const topbar=document.createElement('div');topbar.className='topbar';const brand=$('.brand');document.body.prepend(topbar);topbar.append(brand,panel);
 let busy=false,signup=false,lastUser;
 const switcher=document.createElement('button');switcher.type='button';switcher.id='switch-auth';switcher.textContent='還沒有帳號？註冊';dialog.append(switcher);
 function setMode(value){signup=value;dialog.querySelector('h2').textContent=signup?'註冊新帳號':'登入你的帳號';$('#login-submit').textContent=signup?'註冊':'登入';switcher.textContent=signup?'已有帳號？返回登入':'還沒有帳號？註冊';$('#login-password').autocomplete=signup?'new-password':'current-password';$('#login-password').minLength=signup?8:1;$('#login-password').value='';$('#login-message').textContent=signup?'密碼至少 8 個字元。註冊後請先驗證信箱。':'';}
 const google=document.createElement('button');google.type='button';google.id='google-login';google.textContent='使用 Google 登入';dialog.querySelector('h2').after(google);
 google.onclick=async()=>{if(busy)return;busy=true;google.disabled=true;$('#login-message').textContent='正在連接 Google…';try{const d=await request('google',{method:'POST',body:'{}'});location.assign(d.url);}catch(e){$('#login-message').textContent=e.message;busy=false;google.disabled=false;}};
 const params=new URLSearchParams(location.search);if(params.has('login_error')){params.delete('login_error');history.replaceState(null,'',location.pathname+(params.size?'?'+params:'')+location.hash);dialog.showModal();$('#login-message').textContent='Google 登入未完成或已過期，請再試一次。';}
 switcher.onclick=()=>{if(!busy)setMode(!signup);};
 async function request(path,options={}){const r=await fetch('/api/auth/'+path,{...options,headers:{'Content-Type':'application/json'},credentials:'same-origin'});const data=await r.json();if(!r.ok)throw Error(data.error||'暫時無法登入，請稍後再試。');return data;}
 function show(data){$('#account-email').textContent=data.user?.email||'';$('#open-login').hidden=!!data.user;$('#logout').hidden=!data.user;$('#login-submit').disabled=!data.configured;if(!data.configured)$('#login-message').textContent='登入功能尚未啟用。';if(lastUser!==(data.user?.id||null)){lastUser=data.user?.id||null;window.dispatchEvent(new CustomEvent('encore-auth-change',{detail:{user:data.user||null}}));}}
 async function status(){try{show(await request('session'));}catch{$('#login-message').textContent='無法連線到登入服務。';}}
 $('#open-login').onclick=()=>{dialog.showModal();status();$('#login-email').focus();};dialog.querySelector('.close').onclick=()=>dialog.close();dialog.addEventListener('close',()=>{$('#login-password').value='';$('#login-password').type='password';$('#show-password').textContent='顯示';$('#show-password').setAttribute('aria-pressed','false');});
 $('#show-password').onclick=()=>{const visible=$('#login-password').type==='password';$('#login-password').type=visible?'text':'password';$('#show-password').textContent=visible?'隱藏':'顯示';$('#show-password').setAttribute('aria-pressed',String(visible));};
 $('#login-form').onsubmit=async event=>{event.preventDefault();if(busy)return;busy=true;$('#login-submit').disabled=true;switcher.disabled=true;$('#login-message').textContent=signup?'註冊中…':'登入中…';try{const data=await request(signup?'signup':'login',{method:'POST',body:JSON.stringify({email:$('#login-email').value,password:$('#login-password').value})});if(signup){setMode(false);$('#login-message').textContent=data.message;}else{dialog.close();show(data);}}catch(e){$('#login-message').textContent=e.message;}finally{busy=false;switcher.disabled=false;$('#login-submit').disabled=false;$('#login-password').value='';}};
 $('#logout').onclick=async()=>{if(busy)return;busy=true;$('#logout').disabled=true;try{await request('logout',{method:'POST',body:'{}'});show({configured:true,user:null});}catch{$('#account-email').textContent='登出失敗，請再試一次';}finally{busy=false;$('#logout').disabled=false;}};
 status();setInterval(()=>{if(!busy&&!dialog.open)status();},60000);window.addEventListener('focus',()=>{if(!busy&&!dialog.open)status();});
}
